effect.shader:
const float GOLDEN_ANGLE = 2.39996323;
const float PI = 3.14159265;
void main() {
vec2 uv = acScreenNorm;
float aspect = acScreenSize.x / acScreenSize.y;
float r = blurRadius;
float iterations = float(quality);
vec3 acc = vec3(0.0);
float tot = 0.0;
float sides = float(blurShape);
for (int i = 0; i < 128; i++)
{
if (float(i) >= iterations) break;
float fi = float(i);
float theta = fi * GOLDEN_ANGLE;
float rad = sqrt(fi) / sqrt(iterations);
if (sides > 2.5) {
float deg = 2.0 * PI / sides;
rad *= 1.0 / cos(mod(theta, deg) - deg * 0.5);
}
vec2 off = vec2(cos(theta), sin(theta));
vec2 offset = off * rad * r;
offset.x *= blurWidth / aspect;
offset.y *= blurHeight;
vec3 col = texture2DCv(inputImg.texture, uv + offset).rgb;
float lum = dot(col, vec3(0.299, 0.587, 0.114));
float weight = pow(max(0.0, (lum - highlightThreshold) / (1.0 - min(0.99, highlightThreshold))), highlightGain) + 0.01;
acc += col * weight;
tot += weight;
}
vec3 finalCol = acc / tot;
gl_FragColor = vec4(finalCol, 1.0);
}
